let getPatch=window.location.pathname,url=getPatch.split("/"),page=url[2];fetch("/api/pegawai/gologan/"+page).then(i=>i.json()).then(i=>{console.log(i.data);let o=new Tabulator("#tableDataPegawi",{data:i.data,columns:[{title:"NO",field:"no",width:"5px"},{title:"NIP",field:"nip",editor:"number"},{title:"Nama",field:"nama",editor:"input",width:"25px"},{title:"Golongan",field:"pangkat",editor:"list",editorParams:{values:["IVe","IVd","IVc","IVb","IVa","IIId","IIIc","IIIb","IIIa","IId","IIc","IIb","IIa","XI","X","IX","VIII","VII","VI","V","IV","-"]},width:"10px"},{title:"TMT Pangkat",field:"tmt_pangkat",editor:"date"},{title:"Jabatan",field:"jab",editor:"input"},{title:"TMT Jabatan",field:"tmt_kerja",editor:"date"},{title:"Bidang",field:"bidang"},{title:"ACTION",field:"action",width:"7px",formatter:function(a,e,t){return'<button class="edit-btn">Edit</button>'},cellClick:function(a,e){let t=e.getRow(),l=a.target;console.log(t.getData().nama),fetch("/api/pegawai/data",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({nik:t.getData().nik,nama:t.getData().nama,nip:t.getData().nip,jab:t.getData().jab,pangkat:t.getData().pangkat,tmt_pangkat:t.getData().tmt_pangkat,tmt_kerja:t.getData().tmt_kerja})}).then(n=>n.json()).then(n=>{Swal.fire({title:"Edit Record",text:"Data berhasil diubah atas nama "+t.getData().nama,icon:"success",confirmButtonText:"OK"})}).catch(n=>{console.error("Error:",n),Swal.fire({title:"Edit Record",text:"Data gagal diubah atas nama "+t.getData().nama,icon:"error",confirmButtonText:"OK"})})}},{title:"Lihat Document",field:"action",width:"7px",formatter:function(a,e,t){return'<button class="btn btn-blue">Lihat</button>'},cellClick:function(a,e){let t=e.getRow(),l=a.target;console.log(t.getData().nama),fetch("/api/pegawai/tokenDoc",{method:"post",headers:{"Content-Type":"application/json"},body:JSON.stringify({nik:t.getData().nik,nama:t.getData().nama})}).then(n=>n.json()).then(n=>(console.log(n),window.location.href="/document/pegawaian/"+n.token)).catch(n=>{console.error("Error:",n),Swal.fire({title:"Ops!",text:"Gagal di buka "+t.getData().nama,icon:"error",confirmButtonText:"OK"})})}}],pagination:"local",pageNavigation:"local",paginationSize:20,paginationSizeSelector:[10,20,30,50,100],layout:"fitColumns"});document.getElementById("search-input").addEventListener("keyup",function(){let a=this.value;o.setFilter(e=>Object.values(e).some(t=>String(t).toLowerCase().includes(a.toLowerCase())))}),document.getElementById("download-xlsx").addEventListener("click",function(){o.download("xlsx","data_pegawai.xlsx",{sheetName:"Data Pegawai"})})}).catch(i=>console.error("Error fetching data:",i));async function editRecord(i,o){o.getRow().getElement().classList.add("editing"),o.getRow().getCells().forEach(function(a){let e=document.createElement("input");e.type="text",e.className="form-control",e.value=a.getValue(),a.getElement().innerHTML="",a.getElement().appendChild(e)})}
